// src/components/Hero.tsx
const Hero = () => {
  return (
    <section className="flex flex-col items-center justify-center h-[90vh] text-center px-4">
      <h2 className="text-4xl sm:text-6xl font-bold mb-4">Hi, I'm Juancarlos</h2>
      <p className="text-lg sm:text-2xl text-gray-400 max-w-xl">
        A passionate computer science graduate building responsive full-stack apps.
      </p>
    </section>
  );
};

export default Hero;
